<div class="page-head"><div><p class="section-kicker">Shared sales documents</p><h1>Quotes</h1><p>Create itemized proposals and track secure customer acceptance.</p></div><a class="btn" href="<?= e_attr($basePath) ?>/admin/quotes/edit">New quote</a></div>
<section class="card"><?php if(!$quotes): ?><div class="empty-state"><strong>No quotes yet</strong><span>Create a quote directly or from an inquiry.</span></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Quote</th><th>Customer</th><th>Status</th><th>Valid until</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($quotes as $quote): ?><tr><td><strong><?= e($quote['quote_number']) ?></strong></td><td><?= e($quote['customer_name']) ?><br><span class="muted"><?= e($quote['customer_email']) ?></span></td><td><span class="badge"><?= e(ucwords($quote['status'])) ?></span></td><td><?= e($quote['valid_until']?:'No expiry') ?></td><td><?= e($quote['currency']) ?> <?= number_format($quote['total_minor']/100,2) ?></td><td><a class="btn small secondary" href="<?= e_attr($basePath) ?>/admin/quotes/edit&id=<?= (int)$quote['id'] ?>">Edit</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
